challenges.starterCode:
async function buscarEconomicos(db) {
  // Buscá los productos cuyo precio sea menor o igual a 100.
}

challenges.solutionCode:
async function buscarEconomicos(db) {
  return db.collection("productos").find({ precio: { $lte: 100 } }).toArray();
}

challenges.starterCode:
async function reponerProducto(db, id, unidades) {
  // Actualizá el stock y el estado del producto.
}

challenges.solutionCode:
async function reponerProducto(db, id, unidades) {
  return db.collection("productos").updateOne(
    { _id: id },
    { $inc: { stock: unidades }, $set: { disponible: true } }
  );
}

challenges.starterCode:
async function resumirVentas(db) {
  // Devolvé un pipeline de agregación por categoría.
}

challenges.solutionCode:
async function resumirVentas(db) {
  return db.collection("ventas").aggregate([
    { $match: { estado: "pagada" } },
    { $group: { _id: "$categoria", total: { $sum: "$importe" }, operaciones: { $sum: 1 } } },
    { $sort: { total: -1 } }
  ]).toArray();
}

challenges.starterCode:
async function agregarEtiqueta(db, id, etiqueta) {
  // Agregá una etiqueta sin duplicados.
}

async function buscarEtiquetados(db, etiqueta) {
  // Buscá documentos y devolvé solo los campos solicitados.
}

challenges.solutionCode:
async function agregarEtiqueta(db, id, etiqueta) {
  return db.collection("articulos").updateOne({ _id: id }, { $addToSet: { etiquetas: etiqueta } });
}

async function buscarEtiquetados(db, etiqueta) {
  return db.collection("articulos").find({ etiquetas: etiqueta }, { projection: { _id: 0, nombre: 1, etiquetas: 1 } }).toArray();
}
